class Solution { public boolean isBipartite(int[][] graph) { int[] color=new int[graph.length];java.util.ArrayDeque<Integer> q=new java.util.ArrayDeque<>();for(int s=0;s<graph.length;s++)if(color[s]==0){color[s]=1;q.add(s);while(!q.isEmpty()){int u=q.remove();for(int v:graph[u]){if(color[v]==0){color[v]=-color[u];q.add(v);}else if(color[v]==color[u])return false;}}}return true; } }
